# Manual lock should bias face selection to the user's tap.
old = '''    private Rect chooseBestFace(List<Face> faces, int w, int h) {\n        if (faces == null || faces.isEmpty()) return null;\n        Rect best = null;\n        float bestScore = -999f;\n        for (Face face : faces) {\n            Rect r = face.getBoundingBox();\n            if (r.width() <= 0 || r.height() <= 0) continue;\n            float area = r.width() * r.height() / (float) (w * h);\n            float cx = r.exactCenterX() / w;\n            float cy = r.exactCenterY() / h;\n            float centrality = 1f - (Math.abs(cx - 0.5f) * 0.65f + Math.abs(cy - 0.48f) * 0.35f);\n            float score = area * 8f + centrality;\n            if (score > bestScore) {\n                bestScore = score;\n                best = r;\n            }\n        }\n        return best;\n    }\n'''
new = '''    private Rect chooseBestFace(List<Face> faces, int w, int h) {\n        if (faces == null || faces.isEmpty()) return null;\n        Rect best = null;\n        float bestScore = -999f;\n        for (Face face : faces) {\n            Rect r = face.getBoundingBox();\n            if (r.width() <= 0 || r.height() <= 0) continue;\n            float area = r.width() * r.height() / (float) (w * h);\n            float cx = r.exactCenterX() / w;\n            float cy = r.exactCenterY() / h;\n            float centrality = 1f - (Math.abs(cx - 0.5f) * 0.65f + Math.abs(cy - 0.48f) * 0.35f);\n            float score = area * 8f + centrality;\n            if (manualLockActive) {\n                float dx = cx - manualLockX;\n                float dy = cy - manualLockY;\n                float dist = (float) Math.sqrt(dx * dx + dy * dy);\n                score += Math.max(-4f, 3.5f - dist * 12f);\n                if (manualLockX >= r.left / (float) w && manualLockX <= r.right / (float) w\n                        && manualLockY >= r.top / (float) h && manualLockY <= r.bottom / (float) h) {\n                    score += 6f;\n                }\n            }\n            if (score > bestScore) {\n                bestScore = score;\n                best = r;\n            }\n        }\n        return best;\n    }\n'''
if old not in s:
    raise SystemExit('chooseBestFace target not found')
s = s.replace(old, new)

# Manual subject lock: prefer object containing or nearest the tap; keep updating anchor while tracking.
old = '''    private Rect chooseBestSubject(List<DetectedObject> objects, Rect face, int w, int h) {\n        if (objects == null || objects.isEmpty()) return null;\n        float faceCx = face != null ? face.exactCenterX() : -1f;\n        float faceCy = face != null ? face.exactCenterY() : -1f;\n        Rect best = null;\n        float bestScore = -999f;\n\n        for (DetectedObject object : objects) {\n            Rect r = object.getBoundingBox();\n            if (r.width() <= 0 || r.height() <= 0) continue;\n            float area = r.width() * r.height() / (float) (w * h);\n            if (area < 0.012f || area > 0.93f) continue;\n\n            float cx = r.exactCenterX() / w;\n            float cy = r.exactCenterY() / h;\n            float centerScore = 1f - (Math.abs(cx - 0.5f) * 0.7f + Math.abs(cy - 0.5f) * 0.3f);\n            float sizeScore = Math.min(area, 0.42f) * 3.2f;\n            float score = centerScore + sizeScore;\n\n            if (face != null) {\n                if (containsWithMargin(r, faceCx, faceCy, w * 0.03f, h * 0.03f)) {\n                    score += 3.5f;\n                    float objectToFaceArea = area / Math.max(0.001f,\n                            face.width() * face.height() / (float) (w * h));\n                    if (objectToFaceArea > 2.0f) score += 0.7f;\n                } else {\n                    float dx = (r.exactCenterX() - faceCx) / w;\n                    float dy = (r.exactCenterY() - faceCy) / h;\n                    score -= (float) Math.sqrt(dx * dx + dy * dy) * 3.0f;\n                }\n            }\n\n            if (area > 0.72f) score -= 1.6f;\n            if (score > bestScore) {\n                bestScore = score;\n                best = r;\n            }\n        }\n        return best;\n    }\n'''
new = '''    private Rect chooseBestSubject(List<DetectedObject> objects, Rect face, int w, int h) {\n        if (objects == null || objects.isEmpty()) return null;\n        float faceCx = face != null ? face.exactCenterX() : -1f;\n        float faceCy = face != null ? face.exactCenterY() : -1f;\n        Rect best = null;\n        float bestScore = -999f;\n        float bestLockDistance = 99f;\n\n        for (DetectedObject object : objects) {\n            Rect r = object.getBoundingBox();\n            if (r.width() <= 0 || r.height() <= 0) continue;\n            float area = r.width() * r.height() / (float) (w * h);\n            if (area < 0.012f || area > 0.93f) continue;\n\n            float cx = r.exactCenterX() / w;\n            float cy = r.exactCenterY() / h;\n            float centerScore = 1f - (Math.abs(cx - 0.5f) * 0.7f + Math.abs(cy - 0.5f) * 0.3f);\n            float sizeScore = Math.min(area, 0.42f) * 3.2f;\n            float score = centerScore + sizeScore;\n\n            if (manualLockActive) {\n                float dxLock = cx - manualLockX;\n                float dyLock = cy - manualLockY;\n                float dist = (float) Math.sqrt(dxLock * dxLock + dyLock * dyLock);\n                boolean containsTap = manualLockX >= r.left / (float) w && manualLockX <= r.right / (float) w\n                        && manualLockY >= r.top / (float) h && manualLockY <= r.bottom / (float) h;\n                score += containsTap ? 12f : Math.max(-8f, 5f - dist * 18f);\n                if (dist < bestLockDistance) bestLockDistance = dist;\n            }\n\n            if (face != null) {\n                if (containsWithMargin(r, faceCx, faceCy, w * 0.03f, h * 0.03f)) {\n                    score += 3.5f;\n                    float objectToFaceArea = area / Math.max(0.001f,\n                            face.width() * face.height() / (float) (w * h));\n                    if (objectToFaceArea > 2.0f) score += 0.7f;\n                } else if (!manualLockActive) {\n                    float dx = (r.exactCenterX() - faceCx) / w;\n                    float dy = (r.exactCenterY() - faceCy) / h;\n                    score -= (float) Math.sqrt(dx * dx + dy * dy) * 3.0f;\n                }\n            }\n\n            if (area > 0.72f) score -= 1.6f;\n            if (score > bestScore) {\n                bestScore = score;\n                best = r;\n            }\n        }\n\n        if (manualLockActive && best != null) {\n            float cx = best.exactCenterX() / w;\n            float cy = best.exactCenterY() / h;\n            float dx = cx - manualLockX;\n            float dy = cy - manualLockY;\n            float dist = (float) Math.sqrt(dx * dx + dy * dy);\n            if (dist > 0.34f) return null;\n            manualLockX = 0.82f * manualLockX + 0.18f * cx;\n            manualLockY = 0.82f * manualLockY + 0.18f * cy;\n        }\n        return best;\n    }\n'''
if old not in s:
    raise SystemExit('chooseBestSubject target not found')
s = s.replace(old, new)

s = s.replace(
    '''        float area = subject.width() * subject.height() / (float) (w * h);\n        if (area < 0.025f || area > 0.82f) return false;\n        if (face == null) return area >= 0.05f;\n''',
    '''        float area = subject.width() * subject.height() / (float) (w * h);\n        if (area < 0.012f || area > 0.90f) return false;\n        if (manualLockActive) return true;\n        if (area < 0.025f || area > 0.82f) return false;\n        if (face == null) return area >= 0.05f;\n'''
)

# Replace updateAdvice with scan/return-to-best-angle behavior.
start = s.index('    private void updateAdvice() {')
end = s.index('    private Advice evaluateAdvice() {', start)
new_update = '''    private void updateAdvice() {\n        if (previewBlocked) {\n            showGuidance("KHÔNG ĐỌC ĐƯỢC PREVIEW VIVO", 0, true);\n            coachView.setState(-1f, -1f, 0f, 0f, false, smoothedRoll, 0, true);\n            return;\n        }\n\n        Advice a = evaluateAdvice();\n        long now = android.os.SystemClock.elapsedRealtime();\n\n        if (scanning) {\n            if (subjectReliable && a.score > scanBestScore) {\n                scanBestScore = a.score;\n                scanBestYaw = currentYaw;\n            }\n            if (now < scanEndMs) {\n                showGuidance("LIA CHẬM TRÁI ↔ PHẢI • AI ĐANG SO GÓC", a.score, false);\n                coachView.setState(subjectScreenX, subjectScreenY, subjectScreenW, subjectScreenH,\n                        subjectReliable, smoothedRoll, a.score, false);\n                return;\n            }\n            scanning = false;\n            if (scanButton != null) scanButton.setText("TÌM GÓC");\n            if (scanBestScore >= 0f) {\n                scanTargetYaw = scanBestYaw;\n                scanTargetActive = true;\n            } else {\n                showGuidance("CHƯA ĐỦ DỮ LIỆU • KHÓA CHỦ THỂ RỒI THỬ LẠI", 55, false);\n                return;\n            }\n        }\n\n        if (scanTargetActive) {\n            float delta = normalizeAngle(scanTargetYaw - currentYaw);\n            if (Math.abs(delta) > 5f) {\n                String dir = delta > 0f ? "← XOAY SANG TRÁI " : "XOAY SANG PHẢI → ";\n                showGuidance(dir + Math.round(Math.abs(delta)) + "° • GÓC TỐT HƠN",\n                        Math.max(a.score, Math.round(scanBestScore)), false);\n                coachView.setState(subjectScreenX, subjectScreenY, subjectScreenW, subjectScreenH,\n                        subjectReliable, smoothedRoll, a.score, false);\n                return;\n            }\n            scanTargetActive = false;\n            showGuidance("✓ ĐÃ VỀ GÓC TỐT NHẤT • GIỮ MÁY", Math.round(scanBestScore), false);\n            coachView.setState(subjectScreenX, subjectScreenY, subjectScreenW, subjectScreenH,\n                    subjectReliable, smoothedRoll, Math.round(scanBestScore), false);\n            return;\n        }\n\n        showGuidance(a.text, a.score, false);\n        coachView.setState(subjectScreenX, subjectScreenY, subjectScreenW, subjectScreenH,\n                subjectReliable, smoothedRoll, a.score, false);\n    }\n\n    private float normalizeAngle(float a) {\n        while (a > 180f) a -= 360f;\n        while (a < -180f) a += 360f;\n        return a;\n    }\n\n'''
s = s[:start] + new_update + s[end:]

