# Replace createOverlay: the AI drawing layer becomes click-through; only tiny control windows are touchable.
start = s.index('    private void createOverlay() {')
end = s.index('    private void showGuidance(', start)
new_overlay = '''    private void createOverlay() {\n        overlayRoot = new FrameLayout(this);\n        overlayRoot.setBackgroundColor(Color.TRANSPARENT);\n\n        coachView = new CoachView(this);\n        overlayRoot.addView(coachView, new FrameLayout.LayoutParams(\n                FrameLayout.LayoutParams.MATCH_PARENT,\n                FrameLayout.LayoutParams.MATCH_PARENT));\n\n        guidance = new TextView(this);\n        guidance.setText("AI ĐANG KHỞI ĐỘNG…");\n        guidance.setTextColor(Color.WHITE);\n        guidance.setTextSize(16f);\n        guidance.setGravity(Gravity.CENTER);\n        guidance.setPadding(dp(12), dp(8), dp(12), dp(8));\n        guidance.setBackgroundColor(Color.argb(185, 0, 0, 0));\n        FrameLayout.LayoutParams gp = new FrameLayout.LayoutParams(\n                FrameLayout.LayoutParams.MATCH_PARENT, dp(54));\n        gp.gravity = Gravity.TOP;\n        gp.setMargins(dp(18), dp(48), dp(18), 0);\n        overlayRoot.addView(guidance, gp);\n\n        scoreView = new TextView(this);\n        scoreView.setText("--");\n        scoreView.setTextColor(Color.rgb(95, 255, 120));\n        scoreView.setTextSize(18f);\n        scoreView.setGravity(Gravity.CENTER);\n        scoreView.setBackgroundColor(Color.argb(180, 0, 0, 0));\n        FrameLayout.LayoutParams sp = new FrameLayout.LayoutParams(dp(58), dp(58));\n        sp.gravity = Gravity.LEFT | Gravity.CENTER_VERTICAL;\n        sp.setMargins(dp(12), 0, 0, 0);\n        overlayRoot.addView(scoreView, sp);\n\n        WindowManager.LayoutParams params = new WindowManager.LayoutParams(\n                WindowManager.LayoutParams.MATCH_PARENT,\n                WindowManager.LayoutParams.MATCH_PARENT,\n                Build.VERSION.SDK_INT >= Build.VERSION_CODES.O\n                        ? WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY\n                        : WindowManager.LayoutParams.TYPE_PHONE,\n                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE |\n                        WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE |\n                        WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN |\n                        WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,\n                PixelFormat.TRANSLUCENT);\n        params.gravity = Gravity.TOP | Gravity.LEFT;\n        windowManager.addView(overlayRoot, params);\n\n        createFloatingControls();\n    }\n\n    private TextView makeControl(String text) {\n        TextView v = new TextView(this);\n        v.setText(text);\n        v.setTextColor(Color.WHITE);\n        v.setTextSize(13f);\n        v.setGravity(Gravity.CENTER);\n        v.setPadding(dp(8), dp(5), dp(8), dp(5));\n        v.setBackgroundColor(Color.argb(205, 0, 0, 0));\n        return v;\n    }\n\n    private WindowManager.LayoutParams controlParams(int widthDp, int heightDp, int gravity, int xDp, int yDp) {\n        WindowManager.LayoutParams lp = new WindowManager.LayoutParams(\n                dp(widthDp), dp(heightDp),\n                Build.VERSION.SDK_INT >= Build.VERSION_CODES.O\n                        ? WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY\n                        : WindowManager.LayoutParams.TYPE_PHONE,\n                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE | WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,\n                PixelFormat.TRANSLUCENT);\n        lp.gravity = gravity;\n        lp.x = dp(xDp);\n        lp.y = dp(yDp);\n        return lp;\n    }\n\n    private void createFloatingControls() {\n        lockButton = makeControl("KHÓA CHỦ THỂ");\n        lockButton.setOnClickListener(v -> beginManualLock());\n        windowManager.addView(lockButton, controlParams(112, 38, Gravity.TOP | Gravity.LEFT, 12, 112));\n\n        scanButton = makeControl("TÌM GÓC");\n        scanButton.setOnClickListener(v -> startAngleScan());\n        windowManager.addView(scanButton, controlParams(82, 38, Gravity.TOP | Gravity.LEFT, 132, 112));\n\n        closeView = makeControl("×");\n        closeView.setTextSize(24f);\n        closeView.setOnClickListener(v -> stopSelf());\n        windowManager.addView(closeView, controlParams(42, 42, Gravity.TOP | Gravity.RIGHT, 8, 4));\n    }\n\n    private void beginManualLock() {\n        if (lockCaptureView != null) return;\n        if (screenHeight <= 0) {\n            DisplayMetrics dm = new DisplayMetrics();\n            windowManager.getDefaultDisplay().getRealMetrics(dm);\n            screenWidth = dm.widthPixels;\n            screenHeight = dm.heightPixels;\n        }\n        lockButton.setText("CHẠM CHỦ THỂ");\n        showGuidance("CHẠM VÀO NGƯỜI / VẬT BẠN MUỐN CHỤP", 60, false);\n\n        lockCaptureView = new View(this);\n        lockCaptureView.setBackgroundColor(Color.argb(8, 255, 255, 255));\n        lockCaptureView.setOnTouchListener((v, event) -> {\n            if (event.getAction() == MotionEvent.ACTION_UP) {\n                manualLockX = clamp01(event.getX() / Math.max(1f, v.getWidth()));\n                manualLockY = clamp01(event.getY() / Math.max(1f, v.getHeight()));\n                manualLockActive = true;\n                scanTargetActive = false;\n                if (lockButton != null) lockButton.setText("✓ ĐÃ KHÓA");\n                removeLockCapture();\n                showGuidance("✓ ĐÃ KHÓA CHỦ THỂ • AI SẼ GIỮ ĐÚNG ĐỐI TƯỢNG", 72, false);\n                return true;\n            }\n            return true;\n        });\n\n        int h = Math.max(dp(120), Math.round(screenHeight * (PREVIEW_BOTTOM - PREVIEW_TOP)));\n        WindowManager.LayoutParams lp = new WindowManager.LayoutParams(\n                WindowManager.LayoutParams.MATCH_PARENT, h,\n                Build.VERSION.SDK_INT >= Build.VERSION_CODES.O\n                        ? WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY\n                        : WindowManager.LayoutParams.TYPE_PHONE,\n                WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE | WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,\n                PixelFormat.TRANSLUCENT);\n        lp.gravity = Gravity.TOP | Gravity.LEFT;\n        lp.y = Math.round(screenHeight * PREVIEW_TOP);\n        windowManager.addView(lockCaptureView, lp);\n    }\n\n    private void removeLockCapture() {\n        if (lockCaptureView != null && windowManager != null) {\n            try { windowManager.removeView(lockCaptureView); } catch (Exception ignored) { }\n            lockCaptureView = null;\n        }\n    }\n\n    private void startAngleScan() {\n        if (scanning) return;\n        if (!manualLockActive && subjectPreviewX < 0f) {\n            showGuidance("NÊN KHÓA CHỦ THỂ TRƯỚC KHI TÌM GÓC", 55, false);\n            return;\n        }\n        scanning = true;\n        scanTargetActive = false;\n        scanBestScore = -1f;\n        scanBestYaw = currentYaw;\n        scanEndMs = android.os.SystemClock.elapsedRealtime() + 3200L;\n        if (scanButton != null) scanButton.setText("ĐANG QUÉT…");\n        showGuidance("LIA CHẬM TRÁI ↔ PHẢI TRONG 3 GIÂY", 65, false);\n    }\n\n'''
s = s[:start] + new_overlay + s[end:]

# Sensor handling: landscape leveling + yaw for angle search.
start = s.index('    @Override\n    public void onSensorChanged(SensorEvent event) {')
end = s.index('    private int parseScore(', start)
new_sensor = '''    @Override\n    public void onSensorChanged(SensorEvent event) {\n        if (event.sensor.getType() == Sensor.TYPE_ROTATION_VECTOR) {\n            float[] r = new float[9];\n            float[] o = new float[3];\n            try {\n                SensorManager.getRotationMatrixFromVector(r, event.values);\n                SensorManager.getOrientation(r, o);\n                currentYaw = (float) Math.toDegrees(o[0]);\n            } catch (Exception ignored) { }\n            return;\n        }\n\n        if (event.sensor.getType() != Sensor.TYPE_ACCELEROMETER) return;\n        float raw = (float) Math.toDegrees(Math.atan2(-event.values[0], event.values[1]));\n        float nearestRightAngle = Math.round(raw / 90f) * 90f;\n        float levelError = raw - nearestRightAngle;\n        while (levelError > 45f) levelError -= 90f;\n        while (levelError < -45f) levelError += 90f;\n\n        int q = Math.round(nearestRightAngle) % 360;\n        if (q < 0) q += 360;\n        deviceQuarterTurn = q;\n\n        if (Math.abs(levelError - smoothedRoll) > 28f) {\n            smoothedRoll = levelError;\n        } else {\n            smoothedRoll = 0.82f * smoothedRoll + 0.18f * levelError;\n        }\n\n        if (coachView != null) {\n            coachView.setState(subjectScreenX, subjectScreenY, subjectScreenW, subjectScreenH,\n                    subjectReliable, smoothedRoll,\n                    scoreView != null ? parseScore(scoreView.getText().toString()) : 0,\n                    previewBlocked);\n        }\n    }\n\n'''
s = s[:start] + new_sensor + s[end:]

